        #include &lt;string.h&gt;

        struct Q {
                &#x2F;*@null@*&#x2F; &#x2F;*@only@*&#x2F; char * t;
        };


        &#x2F;*@only@*&#x2F;
        struct Q *
        Q_new (&#x2F;*@only@*&#x2F; char * t)
        {
                struct Q * q = malloc (sizeof *q);
                q-&gt;t = t;
                return q;
        }

        void
        Q_set (struct Q * q, &#x2F;*@only@*&#x2F; char * t)
        {
                free (q-&gt;t);
                q-&gt;t = t;
                return;
        }

        void
        Q_free (&#x2F;*@only@*&#x2F; struct Q * q)
        {
                free (q-&gt;t);
                free (q);
